import"./chunk-ZW5NV4UO.js";var e={en:{title:"Science fiction & fantasy on Mastodon: who and what to follow",description:"Sci-fi and fantasy writers, artists, YouTubers and fans on Mastodon, plus the hashtags worth following. Read it all before you make an account.",heading:"Science fiction & fantasy on Mastodon",intro:["Mastodon has a lively science fiction and fantasy crowd: novelists and short-story writers, magazines, illustrators, critics, Star Trek and Doctor Who fans, and people who simply read a lot.","Starting from an empty timeline is slow. This page gives you a head start: the hashtags people actually use, the people worth following, and the servers where the community gathers."],faq:[{q:"Do I need an account to read this?",a:"No. Every hashtag here opens in Mawkingbird without an account. To follow people and tags you need a Mastodon account on any server; mastodon.social is a fine first choice, and you can move later and keep your followers."},{q:"Is Mastodon a good place for science fiction fans?",a:"Yes. Many SF and fantasy authors, editors and magazines moved to Mastodon, and wandering.shop is a server run for readers and writers of the genre. Conversations are slower than on Twitter and less driven by outrage."},{q:"How do I get onto this list?",a:"Post about science fiction or fantasy, use the hashtags above, and let your profile be suggested to others (your server\u2019s Privacy and reach settings). The list is refreshed every month."}]},de:{title:"Science-Fiction und Fantasy auf Mastodon: wem du folgen kannst",description:"Autorinnen, K\xFCnstler, YouTuber und Fans von Science-Fiction und Fantasy auf Mastodon, dazu die passenden Hashtags. Alles lesbar, bevor du ein Konto anlegst.",heading:"Science-Fiction und Fantasy auf Mastodon",intro:["Auf Mastodon gibt es eine lebendige Szene f\xFCr Science-Fiction und Phantastik: Autorinnen und Autoren, Verlage, Illustratoren, Rezensenten, Fans von Star Trek und Doctor Who und viele, die einfach gern lesen.","Mit einer leeren Startseite anzufangen ist m\xFChsam. Diese Seite hilft dir beim Start: Hashtags, die wirklich benutzt werden, Leute, denen sich das Folgen lohnt, und Server, auf denen sich die Community trifft."],faq:[{q:"Brauche ich ein Konto, um mitzulesen?",a:"Nein. Jeder Hashtag hier \xF6ffnet sich in Mawkingbird ohne Konto. Um Leuten und Hashtags zu folgen, brauchst du ein Mastodon-Konto auf irgendeinem Server; mastodon.social ist ein guter Anfang, und du kannst sp\xE4ter umziehen und deine Follower mitnehmen."},{q:"Warum stehen hier englische Hashtags?",a:"Viele Gespr\xE4che \xFCber Science-Fiction laufen auf Mastodon unter englischen Hashtags, auch von Leuten, die auf Deutsch schreiben. Wir zeigen die aktivsten und dazu deutsche Hashtags, die wachsen sollen."},{q:"Wie komme ich auf diese Liste?",a:"Schreib \xFCber Science-Fiction oder Fantasy, benutze die Hashtags oben und erlaube in den Einstellungen deines Servers (Privatsph\xE4re und Reichweite), dass dein Profil anderen vorgeschlagen wird. Die Liste wird jeden Monat erneuert."}]},fr:{title:"Science-fiction et fantasy sur Mastodon\xA0: qui suivre",description:"Autrices, artistes, vid\xE9astes et fans de science-fiction et de fantasy sur Mastodon, avec les hashtags \xE0 suivre. Tout se lit avant m\xEAme de cr\xE9er un compte.",heading:"Science-fiction et fantasy sur Mastodon",intro:["Mastodon abrite une communaut\xE9 vivante autour des litt\xE9ratures de l\u2019imaginaire\xA0: romanci\xE8res et nouvellistes, revues, illustrateurs, critiques, fans de Star Trek ou de Doctor Who, et beaucoup de grands lecteurs.","Partir d\u2019un fil vide prend du temps. Cette page te donne une longueur d\u2019avance\xA0: les hashtags vraiment utilis\xE9s, les personnes \xE0 suivre et les serveurs o\xF9 la communaut\xE9 se retrouve."],faq:[{q:"Faut-il un compte pour lire\u202F?",a:"Non. Chaque hashtag de cette page s\u2019ouvre dans Mawkingbird sans compte. Pour suivre des personnes et des hashtags, il te faut un compte Mastodon sur n\u2019importe quel serveur\xA0; mastodon.social est un bon d\xE9but, et tu pourras d\xE9m\xE9nager plus tard avec tes abonn\xE9s."},{q:"Pourquoi des hashtags en anglais\u202F?",a:"Beaucoup de conversations sur la SF passent par des hashtags anglais, y compris chez des gens qui \xE9crivent en fran\xE7ais. Nous montrons les plus actifs, et des hashtags fran\xE7ais qui m\xE9ritent de grandir, comme #SFFF et #Imaginaire."},{q:"Comment appara\xEEtre sur cette liste\u202F?",a:"Parle de science-fiction ou de fantasy, utilise les hashtags ci-dessus et autorise ton serveur \xE0 sugg\xE9rer ton profil (param\xE8tres de confidentialit\xE9 et de port\xE9e). La liste est mise \xE0 jour chaque mois."}]},es:{title:"Ciencia ficci\xF3n y fantas\xEDa en Mastodon: a qui\xE9n seguir",description:"Autoras, artistas, youtubers y fans de la ciencia ficci\xF3n y la fantas\xEDa en Mastodon, con las etiquetas que vale la pena seguir. L\xE9elo todo sin crear cuenta.",heading:"Ciencia ficci\xF3n y fantas\xEDa en Mastodon",intro:["En Mastodon hay una comunidad muy viva de ciencia ficci\xF3n y fantas\xEDa: novelistas y cuentistas, revistas, ilustradores, cr\xEDticos, fans de Star Trek y Star Wars, y mucha gente que simplemente lee.","Empezar con un inicio vac\xEDo cuesta. Esta p\xE1gina te da ventaja: las etiquetas que de verdad se usan, la gente a la que vale la pena seguir y los servidores donde se re\xFAne la comunidad."],faq:[{q:"\xBFNecesito una cuenta para leer?",a:"No. Cada etiqueta de esta p\xE1gina se abre en Mawkingbird sin cuenta. Para seguir a personas y etiquetas necesitas una cuenta de Mastodon en cualquier servidor; mastodon.social es un buen comienzo, y puedes mudarte despu\xE9s con tus seguidores."},{q:"\xBFPor qu\xE9 hay etiquetas en ingl\xE9s?",a:"Muchas conversaciones sobre ciencia ficci\xF3n en Mastodon usan etiquetas en ingl\xE9s, tambi\xE9n entre quienes escriben en espa\xF1ol. Mostramos las m\xE1s activas y, junto a ellas, etiquetas en espa\xF1ol como #CienciaFicci\xF3n y #Fantas\xEDa."},{q:"\xBFC\xF3mo aparezco en esta lista?",a:"Publica sobre ciencia ficci\xF3n o fantas\xEDa, usa las etiquetas de arriba y permite que tu servidor sugiera tu perfil a otros (ajustes de privacidad y alcance). La lista se actualiza cada mes."}]},it:{title:"Fantascienza e fantasy su Mastodon: chi seguire",description:"Autrici, artisti, youtuber e fan di fantascienza e fantasy su Mastodon, con gli hashtag da seguire. Puoi leggere tutto prima ancora di creare un account.",heading:"Fantascienza e fantasy su Mastodon",intro:["Su Mastodon c\u2019\xE8 una community vivace di fantascienza e fantasy: romanzieri e autori di racconti, riviste, illustratori, critici, fan di Star Trek e di Star Wars, e tante persone che leggono e basta.","Partire da una home vuota \xE8 lento. Questa pagina ti d\xE0 una spinta: gli hashtag usati davvero, le persone da seguire e i server dove la community si ritrova."],faq:[{q:"Serve un account per leggere?",a:"No. Ogni hashtag di questa pagina si apre in Mawkingbird senza account. Per seguire persone e hashtag ti serve un account Mastodon su qualsiasi server; mastodon.social va benissimo per iniziare, e puoi traslocare dopo portando con te i follower."},{q:"Perch\xE9 ci sono hashtag in inglese?",a:"Molte conversazioni sulla fantascienza passano da hashtag inglesi, anche tra chi scrive in italiano. Mostriamo i pi\xF9 attivi e, accanto, #Fantascienza, che \xE8 gi\xE0 vivo e merita di crescere."},{q:"Come entro in questa lista?",a:"Scrivi di fantascienza o fantasy, usa gli hashtag qui sopra e permetti al tuo server di suggerire il tuo profilo ad altri (impostazioni di privacy e visibilit\xE0). La lista viene aggiornata ogni mese."}]},ja:{title:"Mastodon\uFF08\u30DE\u30B9\u30C8\u30C9\u30F3\uFF09\u306E SF\u30FB\u30D5\u30A1\u30F3\u30BF\u30B8\u30FC\uFF1A\u30D5\u30A9\u30ED\u30FC\u3057\u305F\u3044\u4EBA\u3068\u30BF\u30B0",description:"Mastodon\uFF08\u30DE\u30B9\u30C8\u30C9\u30F3\uFF09\u3067\u6D3B\u52D5\u3059\u308B SF\u30FB\u30D5\u30A1\u30F3\u30BF\u30B8\u30FC\u306E\u4F5C\u5BB6\u3001\u30A2\u30FC\u30C6\u30A3\u30B9\u30C8\u3001YouTuber\u3001\u30D5\u30A1\u30F3\u3068\u3001\u30D5\u30A9\u30ED\u30FC\u3057\u305F\u3044\u30CF\u30C3\u30B7\u30E5\u30BF\u30B0\u3002\u30A2\u30AB\u30A6\u30F3\u30C8\u304C\u306A\u304F\u3066\u3082\u8AAD\u3081\u307E\u3059\u3002",heading:"Mastodon\uFF08\u30DE\u30B9\u30C8\u30C9\u30F3\uFF09\u306E SF\u30FB\u30D5\u30A1\u30F3\u30BF\u30B8\u30FC",intro:["Mastodon \u306B\u306F\u3001SF \u3084\u30D5\u30A1\u30F3\u30BF\u30B8\u30FC\u3092\u66F8\u304F\u4EBA\u3001\u63CF\u304F\u4EBA\u3001\u8AAD\u3080\u4EBA\u306E\u306B\u304E\u3084\u304B\u306A\u30B3\u30DF\u30E5\u30CB\u30C6\u30A3\u304C\u3042\u308A\u307E\u3059\u3002\u4F5C\u5BB6\u3084\u96D1\u8A8C\u3001\u30A4\u30E9\u30B9\u30C8\u30EC\u30FC\u30BF\u30FC\u3001\u30EC\u30D3\u30E5\u30A2\u30FC\u3001\u30B9\u30BF\u30FC\u30C8\u30EC\u30C3\u30AF\u3084\u30B9\u30BF\u30FC\u30FB\u30A6\u30A9\u30FC\u30BA\u306E\u30D5\u30A1\u30F3\u306A\u3069\u3067\u3059\u3002","\u4F55\u3082\u306A\u3044\u30DB\u30FC\u30E0\u304B\u3089\u59CB\u3081\u308B\u306E\u306F\u5927\u5909\u3067\u3059\u3002\u3053\u306E\u30DA\u30FC\u30B8\u3067\u306F\u3001\u5B9F\u969B\u306B\u4F7F\u308F\u308C\u3066\u3044\u308B\u30CF\u30C3\u30B7\u30E5\u30BF\u30B0\u3001\u30D5\u30A9\u30ED\u30FC\u3057\u305F\u3044\u4EBA\u3001\u30B3\u30DF\u30E5\u30CB\u30C6\u30A3\u304C\u96C6\u307E\u308B\u30B5\u30FC\u30D0\u30FC\u3092\u307E\u3068\u3081\u3066\u7D39\u4ECB\u3057\u307E\u3059\u3002"],faq:[{q:"\u8AAD\u3080\u306E\u306B\u30A2\u30AB\u30A6\u30F3\u30C8\u306F\u5FC5\u8981\u3067\u3059\u304B\uFF1F",a:"\u3044\u3044\u3048\u3002\u3053\u306E\u30DA\u30FC\u30B8\u306E\u30CF\u30C3\u30B7\u30E5\u30BF\u30B0\u306F\u3001\u30A2\u30AB\u30A6\u30F3\u30C8\u304C\u306A\u304F\u3066\u3082 Mawkingbird \u3067\u958B\u3051\u307E\u3059\u3002\u4EBA\u3084\u30BF\u30B0\u3092\u30D5\u30A9\u30ED\u30FC\u3059\u308B\u306B\u306F\u3001\u3069\u3053\u304B\u306E\u30B5\u30FC\u30D0\u30FC\u306B Mastodon \u306E\u30A2\u30AB\u30A6\u30F3\u30C8\u304C\u5FC5\u8981\u3067\u3059\u3002\u6700\u521D\u306F mastodon.social \u3067\u5341\u5206\u3067\u3001\u3042\u3068\u304B\u3089\u30D5\u30A9\u30ED\u30EF\u30FC\u3092\u9023\u308C\u3066\u5F15\u3063\u8D8A\u305B\u307E\u3059\u3002"},{q:"\u306A\u305C\u82F1\u8A9E\u306E\u30CF\u30C3\u30B7\u30E5\u30BF\u30B0\u304C\u3042\u308B\u306E\u3067\u3059\u304B\uFF1F",a:"Mastodon \u3067\u306F SF \u306E\u8A71\u984C\u306E\u591A\u304F\u304C\u82F1\u8A9E\u306E\u30CF\u30C3\u30B7\u30E5\u30BF\u30B0\u3067\u4EA4\u308F\u3055\u308C\u3066\u3044\u307E\u3059\u3002\u3044\u3061\u3070\u3093\u6D3B\u767A\u306A\u82F1\u8A9E\u306E\u30BF\u30B0\u3068\u3001\u3053\u308C\u304B\u3089\u80B2\u3066\u305F\u3044\u65E5\u672C\u8A9E\u306E\u30BF\u30B0\u3092\u4E00\u7DD2\u306B\u7D39\u4ECB\u3057\u3066\u3044\u307E\u3059\u3002"},{q:"\u3053\u306E\u30EA\u30B9\u30C8\u306B\u8F09\u308B\u306B\u306F\uFF1F",a:"SF \u3084\u30D5\u30A1\u30F3\u30BF\u30B8\u30FC\u306B\u3064\u3044\u3066\u6295\u7A3F\u3057\u3001\u4E0A\u306E\u30CF\u30C3\u30B7\u30E5\u30BF\u30B0\u3092\u4F7F\u3044\u3001\u30B5\u30FC\u30D0\u30FC\u306E\u30D7\u30E9\u30A4\u30D0\u30B7\u30FC\u8A2D\u5B9A\u3067\u30D7\u30ED\u30D5\u30A3\u30FC\u30EB\u3092\u304A\u3059\u3059\u3081\u306B\u8868\u793A\u3067\u304D\u308B\u3088\u3046\u306B\u3057\u3066\u304F\u3060\u3055\u3044\u3002\u30EA\u30B9\u30C8\u306F\u6BCE\u6708\u66F4\u65B0\u3055\u308C\u307E\u3059\u3002"}]}};export{e as COPY};
